+const FIELD_START = 0;
+const UNQUOTED = 1;
+const QUOTED = 2;
+const AFTER_QUOTE = 3;
+
+function createParser(options = {}) {
+  let delimiter = options.delimiter;
+  if (delimiter === undefined) {
+    delimiter = ',';
+  } else if (
+    typeof delimiter !== 'string' ||
+    delimiter.length !== 1 ||
+    delimiter === '"' ||
+    delimiter === '\r' ||
+    delimiter === '\n'
+  ) {
+    throw new RangeError('delimiter must be one character other than a quote, CR, or LF');
+  }
+
+  let state = FIELD_START;
+  let row = [];
+  let field = '';
+  let recordStarted = false; // current record has consumed any non-separator character
+  let prevCR = false; // previous input character was CR (CRLF detection across chunks)
+  let line = 1;
+  let sawInput = false; // a non-empty chunk has arrived (BOM only valid before this)
+  let ended = false;
+
+  function endRecord(out) {
+    row.push(field);
+    out.push(row);
+    row = [];
+    field = '';
+    recordStarted = false;
+    state = FIELD_START;
+  }
+
+  function push(chunk) {
+    if (ended) throw new Error('push() called after end()');
+    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
+    const out = [];
+    const n = chunk.length;
+    if (n === 0) return out;
+    let i = 0;
+    if (!sawInput) {
+      sawInput = true;
+      if (chunk.charCodeAt(0) === 0xfeff) i = 1;
+    }
+    for (; i < n; i++) {
+      const ch = chunk[i];
+      const wasCR = prevCR;
+      prevCR = ch === '\r';
+      switch (state) {
+        case QUOTED:
+          if (ch === '"') state = AFTER_QUOTE;
+          else field += ch;
+          break;
+        case AFTER_QUOTE:
