            endRecord(out);
          } else {
            field += ch;
          }
      }
      if (ch === '\r' || (ch === '\n' && !wasCR)) line++;
    }
    return out;
  }

  function end() {
    if (ended) return [];
    ended = true;
    if (state === QUOTED) throw new SyntaxError(`Unterminated quoted field at line ${line}`);
    if (!recordStarted) return [];
    const out = [];
    endRecord(out);
    return out;
  }

  return { push, end };
