'use strict';
const assert = require('assert');
const { createParser, parse } = require('./src/csv');

function splits(text, opts) {
  const whole = parse(text, opts);
  for (let a = 0; a <= text.length; a++) {
    for (let b = a; b <= text.length; b++) {
      const p = createParser(opts);
      const got = [];
      for (const c of [text.slice(0, a), '', text.slice(a, b), text.slice(b)]) got.push(...p.push(c));
      got.push(...p.end());
      assert.deepStrictEqual(got, whole, JSON.stringify([text, a, b]));
    }
  }
  return whole;
}
function errLine(text) {
  for (let a = 0; a <= text.length; a++) {
    const p = createParser();
    try { p.push(text.slice(0, a)); p.push(text.slice(a)); p.end(); } catch (e) {
      assert(e instanceof SyntaxError); const m = /line (\d+)/.exec(e.message); assert(m, e.message);
      if (a === 0) var first = m[1]; else assert.strictEqual(m[1], first, JSON.stringify([text, a]));
      continue;
    }
    assert.fail('no error ' + JSON.stringify(text));
  }
  return Number(first);
}

assert.deepStrictEqual(splits(''), []);
assert.deepStrictEqual(splits('\uFEFF'), []);
assert.deepStrictEqual(splits('\n'), [['']]);
assert.deepStrictEqual(splits('\n\n'), [[''], ['']]);
assert.deepStrictEqual(splits('a\r\nb\rc\nd'), [['a'], ['b'], ['c'], ['d']]);
assert.deepStrictEqual(splits('a\r\n'), [['a']]);
assert.deepStrictEqual(splits('\uFEFFa,\uFEFF'), [['a', '\uFEFF']]);
assert.deepStrictEqual(splits('a,,\n,'), [['a', '', ''], ['', '']]);
assert.deepStrictEqual(splits('"x""y","a\r\nb\rc",d"e"\r\n"",""""'), [['x"y', 'a\r\nb\rc', 'd"e"'], ['', '"']]);
assert.deepStrictEqual(splits('a;"b;c"\n', { delimiter: ';' }), [['a', 'b;c']]);
assert.deepStrictEqual(splits('\uD83D\uDE00,x'), [['\uD83D\uDE00', 'x']]);
assert.deepStrictEqual(splits('x,x\n1', { header: true }), [{ x: '1', x_2: '' }]);
assert.strictEqual(errLine('"a" ,b'), 1);
assert.strictEqual(errLine('"a\r\nb\nc\rd"x'), 4);
assert.strictEqual(errLine('a\r\n\r\n"b'), 3);
assert.strictEqual(errLine('"a\r\n'), 2);
for (const d of ['"', '\r', '\n', '', ',,', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);
const p = createParser();
assert.deepStrictEqual(p.push('a\r'), [['a']]);
assert.throws(() => p.push(1), TypeError);
assert.deepStrictEqual(p.end(), []);
assert.deepStrictEqual(p.end(), []);
assert.throws(() => p.push(''), Error);
